import java.util.*;

class Solution {
    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        String items = in.nextLine(); //.trim();
        String prices = in.nextLine(); //.trim();

        //items con
        ArrayList<String> l= new ArrayList<String>();
        if(!items.isEmpty()){
            String[] name = items.split(", ");
            l = new ArrayList<>(Arrays.asList(name));
        }
        //prices con
        ArrayList<Integer> l2= new ArrayList<Integer>();
        int total=0;
         if(!prices.isEmpty()){
            String[] p = prices.split(" ");
            for(String txt : p){
            int pr = Integer.parseInt(txt);
            l2.add(pr);
            total+=pr;
            }
        }

        if(l.isEmpty()){
             System.out.println("Order List: None");
             System.out.println("Total Price: 0");
        }else{
             System.out.println("Order List: "+ String.join(", ",items));
             System.out.println("Total Price: "+total+" PHP");
        }
    }
}

data.statement:
A student spends their last money to order best-selling food items at a popular store. 
Output the complete list of items and calculate the final total price of the order.

<<Note:>> If no items are ordered, output
{{Order List: None}}
{{Total Price: 0 PHP}}
